(()=>{const p={"N04-U01|pilot-serf:three-day-corvee-1797":{"category_id":"N04-U01","item_id":"pilot-serf:three-day-corvee-1797","question":"Какой российский ориентир 1797 года относится к предыстории освобождения?","title":"Какой российский ориентир 1797 года относится к предыстории освобождения?","text":"5 апреля 1797 года по старому стилю Павел I издал акт, известный как Манифест о трёхдневной барщине. Он регулировал труд зависимых крестьян: прямо запрещал принуждение к работе в воскресенье и говорил о распределении остальных дней. Это предшествующая мера ограничения повинностей, а не отмена крепостного права. Дата принятия не доказывает повсеместного соблюдения трёхдневного предела.","gap":"Практика исполнения и разные трактовки ограничения остаются отдельным исследовательским вопросом.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"5 апреля 1797 года по старому стилю Павел I издал акт, известный как Манифест о трёхдневной барщине. Текст прямо запрещал принуждать крестьян к работе в воскресенье. Далее он говорил о равном распределении остальных шести дней между собственным хозяйством крестьянина и работой на помещика.","utf8_sha256":"2f3d2d38679728604780f60ecb2761bc7fa0a2690fcd838afac8ec0f88f5e2b4"},{"paragraph_1based":2,"text":"Датированное предписание и его практическое выполнение — разные вопросы. Публикация музея «Гатчина» показывает различие трактовок: в сенатском объявлении акцент оказался на воскресном запрете. Поэтому нельзя утверждать, что с 1797 года каждый помещик повсеместно соблюдал трёхдневный предел.","utf8_sha256":"af8d42b3e883c83567d2fa2737cc33a65d1670ade0e66ba74f9943953032300d"},{"paragraph_1based":3,"text":"Акт относится к предыстории регулирования крестьянских повинностей и не означает отмены крепостного права. Для темы 1861 важно различать ограничение работы зависимого крестьянина и его личное освобождение.","utf8_sha256":"6a623e2b191848bd81062030b0fff1ae370a94dda957a97f524307af5b2fb3cf"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1ipNrAZDHxQKL51I3HNusdMQzla1uOGu5/view?usp=drivesdk","page":3,"quote":"1797 — Издание Павлом I манифеста о трехдневной барщине.","quote_sha256":"f24e2ce2674a2e108983e8cbe89706aafe11156e6b317690e2c213d043391e0f","source_type":"reference","source_records":["reference-v20:page:158162a8-ca03-51d6-8495-a57eeb25b17e:3"]}],"basis":["CARD_LEARNING.pilot-serf:three-day-corvee-1797.paragraphs","CARD_DATA.items.pilot-serf:three-day-corvee-1797.materials","CARD_LEARNING.pilot-serf:three-day-corvee-1797.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[],"additional_saved_quotes":[]},"N04-U01|pilot-serf:free-cultivators-1803":{"category_id":"N04-U01","item_id":"pilot-serf:free-cultivators-1803","question":"Какое событие соответствует 1803 году и каково его место в крестьянском вопросе?","title":"Какое событие соответствует 1803 году и каково его место в крестьянском вопросе?","text":"1803 год — Указ о вольных хлебопашцах при Александре I. Он относится к законному пути отдельных освобождений, существовавшему до общей реформы Александра II. Ранее принимавшиеся добровольные и местные меры не ликвидировали крепостную зависимость в целом. Поэтому этот ориентир нужно знать отдельно от Манифеста 19 февраля 1861 года.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"В хронологии перед реформой 1861 года указан Указ о вольных хлебопашцах 1803 года. Он относится к царствованию Александра I и позволяет рассматривать освобождение как вопрос с длительной предысторией, а не возникший впервые в 1857 году.","utf8_sha256":"d6f0e84b4e5cbd6ccd13418432d0a8ef89d61b322aa4ffec30f76b8090c7eb36"},{"paragraph_1based":2,"text":"Ранее предпринимавшиеся меры не ликвидировали крепостной зависимости в целом. В Манифесте 1861 года предшествующая политика характеризуется как отдельные добровольные меры или ограниченные местные опыты. Поэтому важно отличать существование законного пути освобождения от обязательного общего изменения статуса крепостных.","utf8_sha256":"b3cd8187a01b0a15cb46b8f1e98aeaf6f27a255a6c27d8a57c75514253e5b912"},{"paragraph_1based":3,"text":"Между 1803 и 1861 годами прошло 58 лет. В этот промежуток помещаются региональные реформы в Прибалтике и меры Николая I. Последовательность показывает накопление опыта при сохранении нерешённости общего крестьянского вопроса.","utf8_sha256":"0727916d019d5064f218fa634152b20b9c888ca504749e45d72ace0adef81337"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":127,"quote":"1803 г. — Указ о «вольных хлебопашцах»","quote_sha256":"800e2ae5672f0abbde9fc73a193decea0d4b90aa4660f4d2bc7460ada97a0fea","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":17,"quote":"а также по Указу о «вольных хлебопашцах» 1803 г.","quote_sha256":"a515031fdd112770fa6855cb380ec3f80cf587399cb7b31c6049f2066968a11c","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:free-cultivators-1803.paragraphs","CARD_DATA.items.pilot-serf:free-cultivators-1803.materials","CARD_LEARNING.pilot-serf:free-cultivators-1803.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Дата и место в теме","text":"В хронологии перед реформой 1861 года указан Указ о вольных хлебопашцах 1803 года. Он относится к царствованию Александра I и позволяет рассматривать освобождение как вопрос с длительной предысторией, а не возникший впервые в 1857 году.","utf8_sha256":"d6f0e84b4e5cbd6ccd13418432d0a8ef89d61b322aa4ffec30f76b8090c7eb36"},{"heading":"От частных мер к общей реформе","text":"Ранее предпринимавшиеся меры не ликвидировали крепостной зависимости в целом. В Манифесте 1861 года предшествующая политика характеризуется как отдельные добровольные меры или ограниченные местные опыты. Поэтому важно отличать существование законного пути освобождения от обязательного общего изменения статуса крепостных.","utf8_sha256":"b3cd8187a01b0a15cb46b8f1e98aeaf6f27a255a6c27d8a57c75514253e5b912"},{"heading":"Хронологическая связь","text":"Между 1803 и 1861 годами прошло 58 лет. В этот промежуток помещаются региональные реформы в Прибалтике и меры Николая I. Последовательность показывает накопление опыта при сохранении нерешённости общего крестьянского вопроса.","utf8_sha256":"0727916d019d5064f218fa634152b20b9c888ca504749e45d72ace0adef81337"},{"heading":"На каких условиях освобождали","text":"По указу Александра I от 20 февраля 1803 года помещик мог по собственной инициативе освободить отдельных крестьян или целое селение вместе с земельным участком. Условия согласовывались сторонами и получали установленное законом утверждение. Освобождённые с землёй могли составить сословие свободных хлебопашцев. Общего принудительного освобождения указ не вводил: решение зависело от владельца и исполнения соглашения. Это конкретный пример ограниченной добровольной меры предшественника, о которой позволяет рассуждать вопрос к Манифесту 1861 года.","utf8_sha256":"a7d0cc7391e73fe68138a92071b91d579268a548e074468e8a64315c75c2b6a6"}],"additional_saved_quotes":[{"sourceKey":"cultivators1803","kind":"Фрагмент источника","sourceType":"external","sourceTitle":"Указ об отпуске помещиками своих крестьян на волю, 20 февраля 1803","sourceUrl":"https://constitution.garant.ru/history/act1600-1918/3050/","page":"","section":"Пункты 1, 3, 4; Российское законодательство X–XX вв., т.6, 1988","quote":"Крестьяне и селения, от помещиков по таковым условиям с землею отпускаемые"}]},"N04-U01|pilot-serf:baltic-1816-1819":{"category_id":"N04-U01","item_id":"pilot-serf:baltic-1816-1819","question":"Какой региональный этап освобождения относится к 1816–1819 годам?","title":"Какой региональный этап освобождения относится к 1816–1819 годам?","text":"1816–1819 годы — отмена крепостного права в Прибалтике по хронологии учебника. Это российский региональный этап, показывающий более раннюю историю освобождения до 1861 года. Нужно сохранить название региона и весь период, не выдавая его за дату общероссийской реформы. Краткая хронологическая строка не раскрывает всех земельных условий этого этапа.","gap":"Земельные условия и распределение региональных актов по годам здесь не восстанавливаются.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Хронология учебника относит отмену крепостного права в Прибалтике к 1816–1819 годам. Это конкретизация сообщения о более раннем освобождении в западных регионах Российской империи.","utf8_sha256":"addec85d62c335f0fa5af143296ced238b3f526597797590d26b183c7904b921"},{"paragraph_1based":2,"text":"Прибалтийский этап произошёл раньше 1861 года: между началом указанного периода и российским Манифестом прошло 45 лет, между завершением периода и Манифестом — 42 года. Сравнивать нужно именно период с датой, а не превращать три года реформ в одно событие без уточнения.","utf8_sha256":"db5cb28c2ad6d9ca58d4374186aadb152b79e9d26cf62d9a6dd59bc0dcd83119"},{"paragraph_1based":3,"text":"Пример позволяет опровергнуть представление, будто до Александра II освобождение нигде не осуществлялось. Однако сам перечень дат не раскрывает земельных условий региональной реформы; их нельзя автоматически переносить на положения 1861 года.","utf8_sha256":"e6d7b791165b8571fd7138092de3702d56f17f3a91113b7e21b0d626e621ad99"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":127,"quote":"1816—1819 гг. — отмена крепостного права в Прибалтике","quote_sha256":"1481502aa028f58c0491566d68313e56656e16aa82d7be07778dd71589743e72","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:baltic-1816-1819.paragraphs","CARD_DATA.items.pilot-serf:baltic-1816-1819.materials","CARD_LEARNING.pilot-serf:baltic-1816-1819.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Региональная предыстория","text":"Хронология учебника относит отмену крепостного права в Прибалтике к 1816–1819 годам. Это конкретизация сообщения о более раннем освобождении в западных регионах Российской империи.","utf8_sha256":"addec85d62c335f0fa5af143296ced238b3f526597797590d26b183c7904b921"},{"heading":"Сопоставление дат","text":"Прибалтийский этап произошёл раньше 1861 года: между началом указанного периода и российским Манифестом прошло 45 лет, между завершением периода и Манифестом — 42 года. Сравнивать нужно именно период с датой, а не превращать три года реформ в одно событие без уточнения.","utf8_sha256":"db5cb28c2ad6d9ca58d4374186aadb152b79e9d26cf62d9a6dd59bc0dcd83119"},{"heading":"Смысл для темы","text":"Пример позволяет опровергнуть представление, будто до Александра II освобождение нигде не осуществлялось. Однако сам перечень дат не раскрывает земельных условий региональной реформы; их нельзя автоматически переносить на положения 1861 года.","utf8_sha256":"e6d7b791165b8571fd7138092de3702d56f17f3a91113b7e21b0d626e621ad99"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:britain-1833":{"category_id":"N04-U01","item_id":"pilot-serf:britain-1833","question":"Какой мировой ориентир 1833 года связан с освобождением зависимого населения?","title":"Какой мировой ориентир 1833 года связан с освобождением зависимого населения?","text":"1833 год — принятие британским парламентом акта об отмене рабства в колониях. Это мировой ориентир, предшествующий российскому Манифесту 1861 года. Колониальный охват закона, его принятие и последующее фактическое осуществление освобождения нужно различать. Краткая учебниковая строка не означает единовременного прекращения любых форм зависимости во всей Британской империи.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"На странице 127 приведён 1833 год. Британский парламент в своей исторической хронологии связывает его с принятием акта об отмене рабства в британских колониях. Поэтому точнее говорить о колониальном охвате закона, а не о единовременной отмене всех форм зависимости в любой части Британской империи.","utf8_sha256":"b7391ef6378545868aadc17aea6ece37db9f53cc1fbf0821afce040ab81b66b0"},{"paragraph_1based":2,"text":"Закон был принят за 28 лет до Манифеста 1861 года. Это позволяет выстроить последовательность международных событий. Но принятие закона и фактическое осуществление освобождения — разные вопросы; их сроки нельзя смешивать.","utf8_sha256":"c98d290f604784a42c9ae69a9c8d23e163b3ce8c8810f88f3e2701a39f819c3d"},{"paragraph_1based":3,"text":"Краткая строка в таблице предназначена для хронологии и не описывает все условия. В объяснении сохранено событие 1833 года и уточнено его содержание по парламентскому источнику. Исходная цитата учебника доступна отдельно и не исправлена задним числом.","utf8_sha256":"7c3fccfd678956ed691405cc634c55ca8bb4fee99e5005c35461ff8772a04112"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":127,"quote":"1833 г. — акт об отмене рабства в Великобритании","quote_sha256":"a0bad1b91de0607de90f2b8cb38800e42607d6ab0308651dcc170fca9f49d13c","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:britain-1833.paragraphs","CARD_DATA.items.pilot-serf:britain-1833.materials","CARD_LEARNING.pilot-serf:britain-1833.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Принятие акта","text":"На странице 127 приведён 1833 год. Британский парламент в своей исторической хронологии связывает его с принятием акта об отмене рабства в британских колониях. Поэтому точнее говорить о колониальном охвате закона, а не о единовременной отмене всех форм зависимости в любой части Британской империи.","utf8_sha256":"b7391ef6378545868aadc17aea6ece37db9f53cc1fbf0821afce040ab81b66b0"},{"heading":"Сравнение с российской реформой","text":"Закон был принят за 28 лет до Манифеста 1861 года. Это позволяет выстроить последовательность международных событий. Но принятие закона и фактическое осуществление освобождения — разные вопросы; их сроки нельзя смешивать.","utf8_sha256":"c98d290f604784a42c9ae69a9c8d23e163b3ce8c8810f88f3e2701a39f819c3d"},{"heading":"Как читать учебниковую формулировку","text":"Краткая строка в таблице предназначена для хронологии и не описывает все условия. В объяснении сохранено событие 1833 года и уточнено его содержание по парламентскому источнику. Исходная цитата учебника доступна отдельно и не исправлена задним числом.","utf8_sha256":"7c3fccfd678956ed691405cc634c55ca8bb4fee99e5005c35461ff8772a04112"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:texas-1845":{"category_id":"N04-U01","item_id":"pilot-serf:texas-1845","question":"Какое американское событие обозначает учебниковая дата 1845?","title":"Какое американское событие обозначает учебниковая дата 1845?","text":"1845 год — присоединение Техаса к США; учебник называет его 28-м штатом. Событие включено как отдельный мировой хронологический ориентир эпохи перед российской реформой. Из присутствия в одной таблице не следует, что присоединение Техаса было причиной отмены крепостного права или проявлением российской роли в американской политике.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает: в 1845 году произошла аннексия Техаса, ставшего 28-м штатом США. Элемент сохраняет эту строку мировой хронологии, которая раньше была доступна только на изображении страницы.","utf8_sha256":"6f970cc02417a820fb93d9122cb8ad93ffbbf9d3544d2d4fe41eab0fe535526f"},{"paragraph_1based":2,"text":"Присоединение Техаса произошло за 16 лет до российской реформы 1861 года. Его можно использовать для установления порядка событий и проверки ориентирования в истории России и мира.","utf8_sha256":"78099b8108f1a9e1a5164a2cfedc004f0f92b46bcb4434965e734f7bf52a901d"},{"paragraph_1based":3,"text":"Техас включён как мировой хронологический ориентир. Из одной таблицы нельзя заключать, что это событие было причиной реформы в России или свидетельствовало о роли России в американской политике. Поэтому оно не помещено автоматически в категорию о значимости России в мировых процессах.","utf8_sha256":"f3a071e8b1a0c9bd5899ad50a1d7c76ec15c9e7fe16e6a900d1e052766018fe9"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":127,"quote":"1845 г. — аннексия Техаса, ставшего 28-м штатом США","quote_sha256":"76f1e63e55c6c67bdee43e6520ad9a698778a1780c278933fc967feba1a670f4","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:texas-1845.paragraphs","CARD_DATA.items.pilot-serf:texas-1845.materials","CARD_LEARNING.pilot-serf:texas-1845.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Событие и дата","text":"Учебник указывает: в 1845 году произошла аннексия Техаса, ставшего 28-м штатом США. Элемент сохраняет эту строку мировой хронологии, которая раньше была доступна только на изображении страницы.","utf8_sha256":"6f970cc02417a820fb93d9122cb8ad93ffbbf9d3544d2d4fe41eab0fe535526f"},{"heading":"Хронологическое положение","text":"Присоединение Техаса произошло за 16 лет до российской реформы 1861 года. Его можно использовать для установления порядка событий и проверки ориентирования в истории России и мира.","utf8_sha256":"78099b8108f1a9e1a5164a2cfedc004f0f92b46bcb4434965e734f7bf52a901d"},{"heading":"Граница смысловой связи","text":"Техас включён как мировой хронологический ориентир. Из одной таблицы нельзя заключать, что это событие было причиной реформы в России или свидетельствовало о роли России в американской политике. Поэтому оно не помещено автоматически в категорию о значимости России в мировых процессах.","utf8_sha256":"f3a071e8b1a0c9bd5899ad50a1d7c76ec15c9e7fe16e6a900d1e052766018fe9"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:world-austria":{"category_id":"N04-U01","item_id":"pilot-serf:world-austria","question":"Какие сроки и содержание австрийского освобождения подтверждены сохранёнными материалами?","title":"Какие сроки и содержание австрийского освобождения подтверждены сохранёнными материалами?","text":"Учебник истории России называет середину XIX века как время окончательной отмены крепостного права в Австрийской империи. Сохранённые дополнительные материалы уточняют преобразования 1848 года и санкционирование закона 7 сентября. Этот пример показывает европейский контекст реформы 1861 года. Положение крестьян по землям империи различалось, поэтому совпадение общего направления освобождения не делает австрийские условия тождественными российским.","gap":"Подробности каждой земли империи и полная практика исполнения закона здесь не устанавливаются.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"В блоке «В это время в мире» окончательная отмена крепостного права в Австрийской империи отнесена к середине XIX века. Источник задаёт период, а не точную дату; в этой карточке он сохранён без произвольного уточнения года.","utf8_sha256":"5022d83b134507d76c7692f9ae153aca97786c44ec161533338330b0f099104b"},{"paragraph_1based":2,"text":"Российская реформа 1861 года входит в тот же широкий исторический процесс изменения личного положения зависимого населения. Сопоставление показывает, что проблема крепостной зависимости не была исключительно российской.","utf8_sha256":"007372f31b839d23ba607af1f94a2e00c86a16f5b2b8ef947c213a0c2da2c9c9"},{"paragraph_1based":3,"text":"Из близости времени нельзя вывести одинаковость реформ. Для сравнения условий освобождения потребовались бы сведения о земле, повинностях, компенсациях и государственном устройстве каждой страны. Здесь проверяется знание международного контекста, а не тождество механизмов реформ.","utf8_sha256":"b60197df7c6fd12927cf4f3ac734fa185451cb06c14f4f6678464116e65caa84"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":123,"quote":"Крепостное право лишь в середине XIX в. было окончательно отменено в Австрийской империи","quote_sha256":"eb656d4e6a899132bbd6c6cbc34c266cff10d4299bb13284a86a215249838906","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:world-austria.paragraphs","CARD_DATA.items.pilot-serf:world-austria.materials","CARD_LEARNING.pilot-serf:world-austria.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Австрийские преобразования 1848 года","text":"Учебник истории России называет общий период — середину XIX века. Дополнительный учебник всеобщей истории описывает реформу 1848 года, а публикация парламента Австрии уточняет санкционирование закона 7 сентября. До преобразования положение крестьян по землям империи различалось: в немецких провинциях сохранялись оброки при личной свободе, в восточных — личная зависимость и барщина.","utf8_sha256":"80b105545d3e771ef4e838274c6b66ff07230740c177f43894e081281bd90eda"},{"heading":"Сравнение по трём признакам","text":"По личному положению оба преобразования устраняли зависимость от помещика. По земельным обязательствам в Австрии закон отменял повинности и различал требования с компенсацией и без неё; в России после личного освобождения временнообязанные продолжали нести повинности до перехода на выкуп. По участию государства австрийская схема компенсации распределяла капитализированную сумму повинностей: треть списывалась, треть платил крестьянин, треть — государство. В российской учебниковой схеме государство предоставляло выкупную ссуду, которую крестьяне затем погашали; её нельзя считать безвозвратной оплатой государством крестьянской доли.","utf8_sha256":"be7a6c356044d5ad41d98f2d893af8b26f9b9b28849d1e4ccfd83fb00e3bae9c"},{"heading":"Вывод и границы сравнения","text":"Общее направление — прекращение личной зависимости при преобразовании земельных отношений. Различались сроки, сохранение повинностей на переходном этапе и характер государственной финансовой помощи. Схему австрийских земель нельзя переносить на всю империю без оговорок: учебник отдельно описывает венгерские меры. В исходной цитате сказано о рыночной стоимости земли; официальный парламентский разбор точнее называет капитализированную сумму повинностей. Цитата сохранена, пересказ разграничивает эти понятия.","utf8_sha256":"204f1d5fed4753639d7d612a95f80436be3dde1aba8f04fbef14995bb457e03f"}],"additional_saved_quotes":[{"sourceKey":"austria131","kind":"Фрагмент источника","sourceType":"external","sourceTitle":"Всеобщая история. 9 класс. § 11","sourceUrl":"https://drive.google.com/file/d/1RuUP3xZAiVq3OTL_UZE33_7_4EkDEZVB/view","page":131,"section":"Всеобщая история. 9 класс. § 11","quote":"В немецких провинциях крестьяне пользовались личной свободой и платили оброк, в восточных провинциях сохранялись личная зависимость и барщина."},{"sourceKey":"austria132","kind":"Фрагмент источника","sourceType":"external","sourceTitle":"Всеобщая история. История Нового времени. XIX — начало XX в. 9 класс. § 11","sourceUrl":"https://drive.google.com/file/d/1RuUP3xZAiVq3OTL_UZE33_7_4EkDEZVB/view","page":132,"section":"Всеобщая история. История Нового времени. XIX — начало XX в. 9 класс. § 11","quote":"В августе 1848 г. парламент разработал компромиссный закон: земля выкупалась по рыночной стоимости, но сам крестьянин выплачивал лишь треть, другую треть — государство, а от выплаты оставшейся трети помещик по закону отказывался."}]},"N04-U01|pilot-serf:crimean-war-chronology":{"category_id":"N04-U01","item_id":"pilot-serf:crimean-war-chronology","question":"Какие события и даты связывают Крымскую войну с эпохой подготовки реформ?","title":"Какие события и даты связывают Крымскую войну с эпохой подготовки реформ?","text":"1853–1856 годы — Крымская война; 1856 год — Парижский конгресс и мирный договор при её завершении. Эти российские и международные ориентиры предшествуют комитетской подготовке и Манифесту 1861 года. Следует отличать период войны от даты дипломатического завершения. Знание дат не заменяет отдельного объяснения того, как поражение выявляло необходимость внутренних изменений.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Крымская война началась в 1853 году и завершилась в 1856 году. Парижский конгресс и заключённый в 1856 году мирный договор относятся к завершению войны. Эти даты образуют хронологическую опору для изучения последующей подготовки реформ.","utf8_sha256":"5832358fd782fa521a26b9116b9d94f090ea339a458b71ea041ed5c6c1b762a3"},{"paragraph_1based":2,"text":"Последовательность такова: начало войны 1853 — завершение войны и Парижский конгресс 1856 — отмена крепостного права 1861. Сам перечень дат не объясняет, почему поражение могло ускорить реформы: для причинного объяснения нужен отдельный материал о положении России и решениях власти.","utf8_sha256":"238bd8516992703237d547b5098adc90fc735fbf16bdb97175bae6939f212cc8"},{"paragraph_1based":3,"text":"На странице 27 общий план Черноморского региона нужно отличать от отдельной схемы обороны Севастополя и карты действий на Балтике. На общем плане Севастополь обозначен цифрой 1, Синоп — цифрой 2; их положение проверяется по береговой линии и подписям, а значение стрелок и значков — по легенде. Сначала определите место и условный знак, затем сопоставьте с названием и периодом войны. Само изображение не объясняет причин крестьянской реформы.","utf8_sha256":"a7ba0957e3e7d9d1083cefc56733b30325a5c1f6db3cba4e50bec4273cafc9a5"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1VOzNvqWiBf8j-YCcC72R3pLiOjonDi-j/view?usp=drivesdk","page":12,"quote":"Крымская война","quote_sha256":"cc9fad448007a12ef37757526a9b0414d7fb63724f79ef479a9083709670258d","source_type":"reference","source_records":["reference-v19:page:cab07a59-1f4c-50db-9af9-3304bf05daf4:12"]},{"source_url":"https://drive.google.com/file/d/1VOzNvqWiBf8j-YCcC72R3pLiOjonDi-j/view?usp=drivesdk","page":12,"quote":"Парижский конгресс","quote_sha256":"c6de1f3cf36fa7f39de3d9e753a86477bddad44100916d1bbca569e38594d127","source_type":"reference","source_records":["reference-v19:page:cab07a59-1f4c-50db-9af9-3304bf05daf4:12"]},{"source_url":"https://drive.google.com/file/d/1DR-Z6HThEyDDHlMRTjflskJPvl0rpNrw/view?usp=drivesdk","page":8,"quote":"Крымская война","quote_sha256":"cc9fad448007a12ef37757526a9b0414d7fb63724f79ef479a9083709670258d","source_type":"reference","source_records":["reference-v19:page:8508b8e4-374b-5389-ab4b-652d384b7c97:8"]},{"source_url":"https://drive.google.com/file/d/1DR-Z6HThEyDDHlMRTjflskJPvl0rpNrw/view?usp=drivesdk","page":8,"quote":"Парижский конгресс","quote_sha256":"c6de1f3cf36fa7f39de3d9e753a86477bddad44100916d1bbca569e38594d127","source_type":"reference","source_records":["reference-v19:page:8508b8e4-374b-5389-ab4b-652d384b7c97:8"]},{"source_url":"https://drive.google.com/file/d/1xxI5J1AQKFbXXkMAryo_qKhn36c6Wsj5/view?usp=drivesdk","page":1,"quote":"1853 начало крымской войны","quote_sha256":"21099cf1add1a2a5731dad277befede02adbb989a66931547da443e7a730aae9","source_type":"reference","source_records":["reference-v19:page:0778f146-a81d-5052-a03d-0bf34454aaa7:1"]},{"source_url":"https://drive.google.com/file/d/1BLkVPDdQqaVXCvCMURru15giOfX7p_ql/view?usp=drivesdk","page":77,"quote":"1853-1856 Крымская война против Турции, Англии, Франции и Сардинии.","quote_sha256":"0f5af2db58495330f5b264aa27e71c6a5b7282f421b383da2257ad64041de31c","source_type":"reference","source_records":["reference-v20:page:6efa9e5f-58a0-5ecc-b078-e0c8c8c13897:77"]},{"source_url":"https://drive.google.com/file/d/1BLkVPDdQqaVXCvCMURru15giOfX7p_ql/view?usp=drivesdk","page":83,"quote":"1856 Парижский конгресс и Парижский трактат.","quote_sha256":"c1a9aa5439e88bb51a2bd518185fb081afcd6edd15f0d2f4d3515cab6ca847c8","source_type":"reference","source_records":["reference-v20:page:6efa9e5f-58a0-5ecc-b078-e0c8c8c13897:83"]},{"source_url":"https://drive.google.com/file/d/1LZewdgCNFyu5SpkSsM84KduLW3P1N_VZ/view?usp=drivesdk","page":2,"quote":"Крымская война (Восточная) 1853-1856 Парижский мир","quote_sha256":"d2fb8d4a07c333d4a163068d951b990963be6508bb0b4ad8b6457e8524348912","source_type":"reference","source_records":["reference-v20:page:78defdda-d9b8-5fb3-99bb-45958642d835:2"]},{"source_url":"https://drive.google.com/file/d/1JVl74billfXE9KfsqXMLLNdoJXdiqmFx/view?usp=drivesdk","page":18,"quote":"Крымская война 1853-1856","quote_sha256":"ee1396d3b01c3df857c9d98dfefee0dd8c2e11322882f0a92a3b11f7bc3dcddd","source_type":"reference","source_records":["reference-v20:page:64860b99-c15e-5af9-9ae7-cf26d5199ec6:18"]},{"source_url":"https://drive.google.com/file/d/1JVl74billfXE9KfsqXMLLNdoJXdiqmFx/view?usp=drivesdk","page":20,"quote":"1856 – Парижский мирный договор","quote_sha256":"c50de4263dee48a1b538da9c82606fd6279c9f3637f02f648168c4146c3a464c","source_type":"reference","source_records":["reference-v20:page:64860b99-c15e-5af9-9ae7-cf26d5199ec6:20"]},{"source_url":"https://drive.google.com/file/d/15fnVebvhiqqd_atqO6DxpCBl5nKXC37l/view","page":27,"quote":"Крымская война 1853-1856 гг.","quote_sha256":"d6ed0f464e973363ca72a0c7c53b88752687f7a06c07be9baef12ef7f64771ee","source_type":"reference","source_records":["reference-v20:page:3f380c3b-55a4-5ced-808a-be830be057fb:27"]}],"basis":["CARD_LEARNING.pilot-serf:crimean-war-chronology.paragraphs","CARD_DATA.items.pilot-serf:crimean-war-chronology.materials","CARD_LEARNING.pilot-serf:crimean-war-chronology.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Содержание","text":"Крымская война началась в 1853 году и завершилась в 1856 году. Парижский конгресс и заключённый в 1856 году мирный договор относятся к завершению войны. Эти даты образуют хронологическую опору для изучения последующей подготовки реформ.","utf8_sha256":"5832358fd782fa521a26b9116b9d94f090ea339a458b71ea041ed5c6c1b762a3"},{"heading":"Связь с темой и различия","text":"Последовательность такова: начало войны 1853 — завершение войны и Парижский конгресс 1856 — отмена крепостного права 1861. Сам перечень дат не объясняет, почему поражение могло ускорить реформы: для причинного объяснения нужен отдельный материал о положении России и решениях власти.","utf8_sha256":"238bd8516992703237d547b5098adc90fc735fbf16bdb97175bae6939f212cc8"},{"heading":"Как прочитать карту","text":"На странице 27 общий план Черноморского региона нужно отличать от отдельной схемы обороны Севастополя и карты действий на Балтике. На общем плане Севастополь обозначен цифрой 1, Синоп — цифрой 2; их положение проверяется по береговой линии и подписям, а значение стрелок и значков — по легенде. Сначала определите место и условный знак, затем сопоставьте с названием и периодом войны. Само изображение не объясняет причин крестьянской реформы.","utf8_sha256":"a7ba0957e3e7d9d1083cefc56733b30325a5c1f6db3cba4e50bec4273cafc9a5"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:world-timeline-1856-1869":{"category_id":"N04-U01","item_id":"pilot-serf:world-timeline-1856-1869","question":"Какие мировые ориентиры таблица учебника даёт для 1856, 1860, 1868 и 1869 годов?","title":"Какие мировые ориентиры таблица учебника даёт для 1856, 1860, 1868 и 1869 годов?","text":"1856 — обнаружение останков неандертальца в долине Неандер; 1860 — избрание Линкольна президентом США; 1868 — указанный таблицей выход романа Ж. Верна «Дети капитана Гранта»; 1869 — открытие Суэцкого канала. Научное, политическое, культурное и инфраструктурное события образуют контекст эпохи российской реформы, но не становятся от одного соседства в таблице её причинами.","gap":"1868 сохранён как ориентир конкретной таблицы, без исследования всей истории публикации романа.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"В 1856 году в долине реки Неандер обнаружили останки древнего человека — неандертальца. В 1860 году президентом США был избран А. Линкольн. В хронологии это научный и политический ориентиры, предшествующие российской реформе 1861 года.","utf8_sha256":"36a5cb6835ae415b90ad49f3e43e295c6299c3e642e0eb01584e4c2555c0528e"},{"paragraph_1based":2,"text":"Учебник указывает 1868 год для выхода романа Ж. Верна «Дети капитана Гранта» и 1869 год для открытия Суэцкого канала. Эти строки относятся к культурному и инфраструктурному контексту эпохи. Здесь сохранена датировка таблицы учебника; история публикации романа по частям отдельно не рассматривается.","utf8_sha256":"5fa4f7033e4a3015bee86fb48f0571ac6c07a52b76efba513352dd12553aa99c"},{"paragraph_1based":3,"text":"Порядок по данной таблице: открытие останков — избрание Линкольна — реформа в России — роман Верна — открытие канала. Для каждого пункта нужно знать не только год, но и событие. Одновременность или близость дат сама по себе не устанавливает причинную связь между ними.","utf8_sha256":"17b93066bd225c225f7b2c17ea6962d971abdc616608dcf30ac1cb496356284c"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":120,"quote":"1856 г. — в долине р. Неандер (Рейнская провинция) обнаружены окаменелые останки древнего человека — неандертальца","quote_sha256":"22c87e64f866a9a656e7e434348cbaa653f70cb508f448bef255df927f5f58c1","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":120,"quote":"1860 г. — избрание президентом США А. Линкольна","quote_sha256":"7648d2f4caea9056a2923f007bdf789db705066f33de571afeb8cc3f150b6043","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":120,"quote":"1868 г. — выход романа Ж. Верна «Дети капитана Гранта»","quote_sha256":"725220ad8188153f700dca4c917a3187810290ece0b30f46ca8915a44d9c1fdf","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":120,"quote":"1869 г. — открытие Суэцкого канала","quote_sha256":"c6a2a3b74eda8e6c60ff4c53f0332c442891b81f48a5333be3c070207720998f","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:world-timeline-1856-1869.paragraphs","CARD_DATA.items.pilot-serf:world-timeline-1856-1869.materials","CARD_LEARNING.pilot-serf:world-timeline-1856-1869.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"1856 и 1860 годы","text":"В 1856 году в долине реки Неандер обнаружили останки древнего человека — неандертальца. В 1860 году президентом США был избран А. Линкольн. В хронологии это научный и политический ориентиры, предшествующие российской реформе 1861 года.","utf8_sha256":"36a5cb6835ae415b90ad49f3e43e295c6299c3e642e0eb01584e4c2555c0528e"},{"heading":"1868 и 1869 годы","text":"Учебник указывает 1868 год для выхода романа Ж. Верна «Дети капитана Гранта» и 1869 год для открытия Суэцкого канала. Эти строки относятся к культурному и инфраструктурному контексту эпохи. Здесь сохранена датировка таблицы учебника; история публикации романа по частям отдельно не рассматривается.","utf8_sha256":"5fa4f7033e4a3015bee86fb48f0571ac6c07a52b76efba513352dd12553aa99c"},{"heading":"Работа с последовательностью","text":"Порядок по данной таблице: открытие останков — избрание Линкольна — реформа в России — роман Верна — открытие канала. Для каждого пункта нужно знать не только год, но и событие. Одновременность или близость дат сама по себе не устанавливает причинную связь между ними.","utf8_sha256":"17b93066bd225c225f7b2c17ea6962d971abdc616608dcf30ac1cb496356284c"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:russia-context-1858-1868":{"category_id":"N04-U01","item_id":"pilot-serf:russia-context-1858-1868","question":"Какие внешнеполитический и культурный ориентиры России нужно отличать от крестьянской реформы?","title":"Какие внешнеполитический и культурный ориентиры России нужно отличать от крестьянской реформы?","text":"1858 год — Айгунский договор с Китаем, закрепивший за Россией левый берег Амура. 1868 год в таблице учебника — выход романа Л. Толстого «Война и мир». Российская реформа 1861 года относится к иной, социально-правовой сфере. Сохранение даты, события и сферы позволяет представить развитие страны, не смешивая договор, произведение культуры и механизм освобождения.","gap":"1868 передаёт датировку таблицы, а не полную историю написания и публикации романа.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"В 1858 году был заключён Айгунский договор с Китаем, закрепивший за Россией левый берег Амура. Это внешнеполитическое событие. В том же году Секретный комитет преобразовали в Главный, но совпадение года не делает договор частью механизма освобождения крестьян.","utf8_sha256":"01c76c18061cbd402c1e5b5b1583b985abaefb1bd089a13d7a28d48bf3139cdb"},{"paragraph_1based":2,"text":"В таблице учебника выход романа Л. Толстого «Война и мир» обозначен 1868 годом. Эта дата сохранена как ориентир конкретной таблицы, без подмены её исследованием всей истории публикации произведения. Она показывает присутствие культурного развития в общей картине эпохи.","utf8_sha256":"ef25bb61f17500722a4f20a05755d7a2d88a35488ce1493ec67a4afebd7630bf"},{"paragraph_1based":3,"text":"События удобно разделить по сферам: реформа 1861 года — социально-правовые изменения; Айгунский договор — внешняя политика; роман Толстого — культура. Такое разделение помогает отвечать на вопрос о развитии страны, не смешивая разные процессы в один список причин отмены крепостного права.","utf8_sha256":"41848791060712c71e8e6364eb63644423e3208d739b01a923a05f585aa1defd"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":120,"quote":"1858 г. — Айгунский договор с Китаем, закрепление за Россией левого берега р. Амур","quote_sha256":"3a86baeb926e0c1e1c1e6370ebf32fe605315b16937d8309d464602a0941ff4f","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":120,"quote":"1868 г. — выход романа Л. Толстого «Война и мир»","quote_sha256":"e3816f5b4885d10c9c2d748e6614fc945a3c82c5333d846339167d3b3dd32691","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:russia-context-1858-1868.paragraphs","CARD_DATA.items.pilot-serf:russia-context-1858-1868.materials","CARD_LEARNING.pilot-serf:russia-context-1858-1868.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:baltic-1816-1819","source_learning_sha256":"a949410d85c81565ef87128c9946441bdcccb1f0d515a4f4de69891bf79e0564","source_item_sha256":"f063a4cd8f744d0a524aee4d891bfc43253683b0c2b72b5ae241e13869663055"},{"item_id":"pilot-serf:britain-1833","source_learning_sha256":"dab8622959f3f02540dcbd06854e53fde53eb33ca29d6524937a4ad09f53bb0e","source_item_sha256":"c4740d36cff90d597a494a1dc9dc8abd1ccafcdcf074b56c9b504b3d41e4d43d"},{"item_id":"pilot-serf:crimean-war-chronology","source_learning_sha256":"522b992d1a41fd118b5a57f37a837f3321e3e712053cc9883bd00ff6aa6b74b5","source_item_sha256":"689963101993b9490e2ff20056e8d2170d4422dc7b4eac1e96461162d4ed1432"},{"item_id":"pilot-serf:free-cultivators-1803","source_learning_sha256":"eb72629245199318b7b1a53f1a19ff6a998aeec3631b28805f7cf2871557f3ee","source_item_sha256":"18376e798cd391181462653f1ebe376033d8a7000b22c3eb943ddd4033205374"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:russia-context-1858-1868","source_learning_sha256":"fe75c08ccad2a1e3356af7ea07d4fe881a0e5010886bb119833a2d59f428d948","source_item_sha256":"e5518cb5d37d64f08337fb46fa7bb004558f1676d0a2d7d6e84db03e2e991153"},{"item_id":"pilot-serf:texas-1845","source_learning_sha256":"fd36e5d751ed063e5108849e09704e8125b70815df97c9ce3fd1090687d43fd9","source_item_sha256":"2fec5866bf8dfea176479b27a4fd792e75cbe3a7ad76a899ae2fe7cce8218160"},{"item_id":"pilot-serf:three-day-corvee-1797","source_learning_sha256":"650b726a86b6712ff7da98de6265906d4d1f9397779a5a74915b564555e568e8","source_item_sha256":"1a4b0c66c348795c75de5484f88550ee399f0e70551ef1e73983616b01288d18"},{"item_id":"pilot-serf:world-austria","source_learning_sha256":"bf9815155c3916384b0c63b9a87dcb2a9beebae61389ea30b790118da866395f","source_item_sha256":"076d4c01eedb6f0a50a5792e75eed180fccad34c983fa5240322d5e7d4475136"},{"item_id":"pilot-serf:world-timeline-1856-1869","source_learning_sha256":"dcf25bfbeac42f681c9d57a9925bd12155b1156bd733a88b92b88b4a7001427a","source_item_sha256":"36182b0077262b5543619c671b003aadd02b57e2ee322c2bd31d5a6e076f29cf"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Айгунский договор","text":"В 1858 году был заключён Айгунский договор с Китаем, закрепивший за Россией левый берег Амура. Это внешнеполитическое событие. В том же году Секретный комитет преобразовали в Главный, но совпадение года не делает договор частью механизма освобождения крестьян.","utf8_sha256":"01c76c18061cbd402c1e5b5b1583b985abaefb1bd089a13d7a28d48bf3139cdb"},{"heading":"Литературный ориентир","text":"В таблице учебника выход романа Л. Толстого «Война и мир» обозначен 1868 годом. Эта дата сохранена как ориентир конкретной таблицы, без подмены её исследованием всей истории публикации произведения. Она показывает присутствие культурного развития в общей картине эпохи.","utf8_sha256":"ef25bb61f17500722a4f20a05755d7a2d88a35488ce1493ec67a4afebd7630bf"},{"heading":"Систематизация","text":"События удобно разделить по сферам: реформа 1861 года — социально-правовые изменения; Айгунский договор — внешняя политика; роман Толстого — культура. Такое разделение помогает отвечать на вопрос о развитии страны, не смешивая разные процессы в один список причин отмены крепостного права.","utf8_sha256":"41848791060712c71e8e6364eb63644423e3208d739b01a923a05f585aa1defd"}],"additional_saved_quotes":[]}};const a=window.CARD_REVIEWED_APPLICATIONS.answers;for(const k of Object.keys(p)){if(a[k])throw new Error("Unexpected accepted-answer overwrite "+k);}Object.assign(a,p);})();